"use client";
import * as React from "react";
import { cn } from "@/lib/utils";
import { mixNumber, numberParts, rollingTarget } from "@/lib/cojeev/number-motion";
import { createMotionLane, motionTokens } from "@/lib/cojeev-motion/choreography";
import { getServerSettingsSnapshot, getSettingsSnapshot, subscribeSettings } from "@/lib/cojeev-motion/settings";
import { useMotionVisibility } from "@/lib/cojeev-motion/use-motion-visibility";

export type AnimatedNumberProps = Omit<React.ComponentProps<"span">, "children"> & {
  value: number;
  locale?: string;
  format?: Intl.NumberFormatOptions;
  /** Transition time in milliseconds, bounded to 0–2000 and scaled by Flow speed. */
  duration?: number;
  /** Count through values, roll each digit, or count in twelve drawn poses. */
  treatment?: "count" | "roll" | "steps";
  /** Optional starting value for the first visible entrance. SSR always shows the final value. */
  from?: number;
  /** Text for NaN or infinite values; never presents missing data as zero. */
  fallback?: string;
};

type Lane = ReturnType<typeof createMotionLane>;
type Wheel = { element: HTMLSpanElement; lane: Lane; reveal: Lane };

function makeNumberPainter(element: HTMLSpanElement, initial: number | null) {
  let current = initial, target = initial, signature = "", mode = "", formatter = new Intl.NumberFormat("en-US");
  const wheels = new Map<string, Wheel>();
  const resetWheels = () => { wheels.forEach(wheel => { wheel.lane.dispose(); wheel.reveal.dispose(); }); wheels.clear(); };
  let countLane: Lane | null = null;
  const clear = () => { countLane?.dispose(); countLane = null; resetWheels(); element.replaceChildren(); };
  return {
    update(value: number | null, options: { formatter: Intl.NumberFormat; signature: string; treatment: string; duration: number; still: boolean; fallback: string; start?: number }) {
      const changed = signature !== options.signature || mode !== options.treatment;
      if (changed) { clear(); signature = options.signature; mode = options.treatment; }
      formatter = options.formatter;
      if (value === null) { clear(); current = target = null; element.textContent = options.fallback; return; }
      if (options.start !== undefined) { current = options.start; target = options.start; resetWheels(); }
      const start = current ?? value;
      const previousTarget = target ?? start;
      target = value;
      const still = options.still || options.duration === 0;
      const transition = { duration: options.duration / 1000, ease: motionTokens.ease.settle };
      if (mode === "roll") {
        countLane?.dispose(); countLane = null;
        const parts = numberParts(formatter, value);
        const previousParts = new Map(numberParts(formatter, start).map(part => [part.key, part]));
        const keep = new Set(parts.map(part => part.key));
        for (const [key, wheel] of wheels) if (!keep.has(key)) { wheel.lane.dispose(); wheel.reveal.dispose(); wheel.element.remove(); wheels.delete(key); }
        const fragment = document.createDocumentFragment();
        let run: HTMLElement | null = null;
        for (const part of parts) {
          const numeric = /^(integer|fraction|decimal|group):/.test(part.key);
          if (numeric && !run) { run = document.createElement("bdi"); run.dir = "ltr"; run.className = "v-animated-number__run"; fragment.append(run); }
          if (!numeric) run = null;
          const parent = run ?? fragment;
          if (part.digit === undefined || !part.glyphs) { const literal = document.createElement("span"); literal.textContent = part.text; parent.append(literal); continue; }
          let wheel = wheels.get(part.key);
          if (!wheel) {
            const cell = document.createElement("span"); cell.className = "v-animated-number__digit";
            const track = document.createElement("span"); track.className = "v-animated-number__track";
            const first = document.createElement("span"), second = document.createElement("span"); track.append(first, second); cell.append(track);
            const glyphs = part.glyphs;
            const paint = (position: number) => { const integer = Math.floor(position), fraction = position - integer; first.textContent = glyphs[((integer % 10) + 10) % 10]; second.textContent = glyphs[(((integer + 1) % 10) + 10) % 10]; track.style.translate = `0 ${-fraction * 50}%`; };
            const previous = previousParts.get(part.key)?.digit;
            const origin = still ? part.digit : previous ?? 0;
            const lane = createMotionLane(origin, paint); paint(origin);
            const paintReveal = (amount: number) => { cell.style.opacity = String(amount); cell.style.translate = `0 ${(1 - amount) * .2}em`; };
            const revealed = still || previous !== undefined ? 1 : 0;
            const reveal = createMotionLane(revealed, paintReveal); paintReveal(revealed);
            wheel = { element: cell, lane, reveal }; wheels.set(part.key, wheel);
          }
          parent.append(wheel.element);
          if (still) { wheel.lane.jump(part.digit); wheel.reveal.jump(1); }
          else {
            const destination = rollingTarget(wheel.lane.get(), part.digit, Math.sign(value - previousTarget) || 1);
            if (Math.abs(destination - wheel.lane.get()) > 1e-7) wheel.lane.to(destination, transition);
            wheel.reveal.to(1, transition);
          }
        }
        element.replaceChildren(fragment);
        current = value;
        return;
      }
      resetWheels();
      countLane?.dispose();
      if (still || start === value) { current = value; element.textContent = formatter.format(value); return; }
      let pose = -1;
      const paint = (progress: number) => {
        const nextPose = Math.min(12, Math.floor(progress * 12));
        if (mode === "steps" && nextPose === pose) return;
        pose = nextPose;
        const amount = mode === "steps" ? nextPose / 12 : progress;
        current = mixNumber(start, value, amount);
        const text = formatter.format(current);
        if (mode !== "steps" || amount === 1) { element.textContent = text; return; }
        const fragment = document.createDocumentFragment();
        Array.from(text).forEach((character, index) => { const glyph = document.createElement("span"); glyph.textContent = character; glyph.className = "v-animated-number__pose"; glyph.style.rotate = `${Math.sin((pose + 1) * 2.7 + index * 1.9) * 1.8}deg`; glyph.style.translate = `0 ${Math.cos(pose * 1.7 + index) * .025}em`; fragment.append(glyph); });
        element.replaceChildren(fragment);
      };
      countLane = createMotionLane(0, paint); paint(0);
      countLane.to(1, transition, () => { current = value; element.textContent = formatter.format(value); });
    },
    dispose() { clear(); },
  };
}

/** Locale-aware numbers with a final accessible value and interruptible visual motion. */
export function AnimatedNumber({ value, locale = "en-US", format, duration = 500, treatment = "count", from, fallback = "—", className, ref, ...props }: AnimatedNumberProps) {
  const host = React.useRef<HTMLSpanElement>(null), visual = React.useRef<HTMLSpanElement>(null);
  const painter = React.useRef<ReturnType<typeof makeNumberPainter> | null>(null);
  const entered = React.useRef(false);
  const safeValue = Number.isFinite(value) ? value : null;
  const formatKey = JSON.stringify(format ?? {});
  const formatter = React.useMemo(() => new Intl.NumberFormat(locale, JSON.parse(formatKey)), [locale, formatKey]);
  const formatted = safeValue === null ? fallback : formatter.format(safeValue);
  const [initial] = React.useState(formatted);
  const { enabled, inView } = useMotionVisibility(host);
  const settings = React.useSyncExternalStore(subscribeSettings, getSettingsSnapshot, getServerSettingsSnapshot);
  const [localQuiet, setLocalQuiet] = React.useState(false);
  const still = !enabled || !inView || localQuiet;
  const ownedRef = React.useCallback((node: HTMLSpanElement | null) => { host.current = node; if (typeof ref === "function") return ref(node); if (ref) ref.current = node; }, [ref]);
  React.useLayoutEffect(() => {
    const element = visual.current;
    if (!element) return;
    const instance = makeNumberPainter(element, safeValue); painter.current = instance;
    return () => { instance.dispose(); painter.current = null; };
  // The painter owns its visual DOM and receives all changing props below.
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);
  React.useEffect(() => {
    const element = host.current; if (!element) return;
    const update = () => setLocalQuiet(Boolean(element.closest('[data-flow="off"],[data-no-glide]')));
    const observer = new MutationObserver(update);
    for (let ancestor: Element | null = element; ancestor; ancestor = ancestor.parentElement) observer.observe(ancestor, { attributes: true, attributeFilter: ["data-flow", "data-no-glide"] });
    update(); return () => observer.disconnect();
  }, []);
  React.useLayoutEffect(() => {
    const entrance = !entered.current && enabled && inView && !localQuiet;
    if (inView && enabled) entered.current = true;
    painter.current?.update(safeValue, { formatter, signature: `${locale}:${formatKey}`, treatment, duration: (Number.isFinite(duration) ? Math.min(2000, Math.max(0, duration)) : 500) / settings.flow.speed, still, fallback, start: entrance && Number.isFinite(from) ? from : undefined });
  }, [safeValue, formatter, formatKey, locale, treatment, duration, still, fallback, from, enabled, inView, localQuiet, settings.flow.speed]);
  return <span {...props} ref={ownedRef} data-slot="animated-number" data-treatment={treatment} data-quiet={still} className={cn("v-animated-number", className)}>
    <span className="v-animated-number__accessible">{formatted}</span>
    <span ref={visual} className="v-animated-number__visual" aria-hidden="true">{initial}</span>
  </span>;
}

export type NumberPart = { key: string; text: string; digit?: number; glyphs?: string[] };

/** Keep Intl's punctuation and bidi literals intact; only decimal digits become wheels. */
export function numberParts(formatter: Intl.NumberFormat, value: number): NumberPart[] {
  const resolved = formatter.resolvedOptions();
  const digits = new Intl.NumberFormat(resolved.locale, { useGrouping: false, numberingSystem: resolved.numberingSystem });
  const glyphs = Array.from({ length: 10 }, (_, digit) => digits.format(digit));
  const parts = formatter.formatToParts(value);
  const integerLength = parts.filter(part => part.type === "integer").reduce((length, part) => length + Array.from(part.value).length, 0);
  let integer = integerLength, fraction = 0;
  const occurrences: Record<string, number> = {};
  return parts.flatMap(part => {
    if (part.type === "integer" || part.type === "fraction") return Array.from(part.value).map(text => {
      const digit = glyphs.indexOf(text);
      const key = part.type === "integer" ? `integer:${--integer}` : `fraction:${fraction++}`;
      return { key, text, ...(digit < 0 ? {} : { digit, glyphs }) };
    });
    const occurrence = occurrences[part.type] ?? 0;
    occurrences[part.type] = occurrence + 1;
    return [{ key: `${part.type}:${occurrence}`, text: part.value }];
  });
}

/** Choose the next matching digit without resetting an interrupted fractional position. */
export function rollingTarget(current: number, digit: number, direction: number) {
  const cycle = Math.floor(current / 10) * 10;
  let target = cycle + digit;
  if (direction >= 0 && target < current - 1e-7) target += 10;
  if (direction < 0 && target > current + 1e-7) target -= 10;
  return target;
}

export function mixNumber(from: number, to: number, progress: number) {
  if (progress >= 1) return to;
  if (progress <= 0) return from;
  return Math.sign(from) === Math.sign(to) ? from + (to - from) * progress : from * (1 - progress) + to * progress;
}

/** Base-aware decimal stepping, with a bounded precision that avoids visible floating point tails. */
export function stepNumber(value: number | null, direction: 1 | -1, step = 1, min?: number, max?: number) {
  const amount = Number.isFinite(step) && step > 0 ? step : 1;
  const lower = Number.isFinite(min) ? min! : -Infinity;
  const upper = Number.isFinite(max) ? Math.max(lower, max!) : Infinity;
  const base = Number.isFinite(lower) ? lower : 0;
  if (value === null || !Number.isFinite(value)) return Math.min(upper, Math.max(lower, Number.isFinite(lower) ? lower : Number.isFinite(upper) && upper < 0 ? upper : 0));
  const position = (value - base) / amount;
  const nearest = Math.round(position);
  const aligned = Math.abs(position - nearest) < 1e-9;
  const next = aligned ? nearest + direction : direction > 0 ? Math.ceil(position) : Math.floor(position);
  const result = base + next * amount;
  const decimals = (number: number) => { const [mantissa, exponent = "0"] = String(number).split("e"); return Math.max(0, (mantissa.split(".")[1]?.length ?? 0) - Number(exponent)); };
  const precision = Math.max(decimals(base), decimals(amount));
  // Preserve all integer digits; only remove fractional arithmetic tails at the step's precision.
  const clean = Number.isFinite(result) ? Number(precision <= 100 ? result.toFixed(precision) : result.toPrecision(15)) : value;
  return Math.min(upper, Math.max(lower, clean));
}

/** Parse editable decimal text in the chosen numbering system; punctuation remains data until commit. */
export function parseNumberInput(text: string, locale = "en-US"): number | null | undefined {
  if (!text.trim()) return null;
  const formatter = new Intl.NumberFormat(locale);
  const parts = formatter.formatToParts(-12345.6);
  const decimal = parts.find(part => part.type === "decimal")?.value ?? ".";
  const group = parts.find(part => part.type === "group")?.value;
  const minus = parts.find(part => part.type === "minusSign")?.value ?? "-";
  let normalized = text.trim().replace(/[\u061c\u200e\u200f]/g, "");
  if (group) normalized = normalized.split(group).join("");
  normalized = normalized.split(decimal).join(".").split(minus).join("-");
  const digits = new Intl.NumberFormat(locale, { useGrouping: false });
  for (let digit = 0; digit < 10; digit++) normalized = normalized.split(digits.format(digit)).join(String(digit));
  if (!/^[+-]?(?:\d+(?:\.\d*)?|\.\d+)(?:e[+-]?\d+)?$/i.test(normalized)) return undefined;
  const value = Number(normalized);
  return Number.isFinite(value) ? value : undefined;
}

/** Editable text preserves the number's full significant precision, including scientific notation. */
export function numberInputText(value: number, locale = "en-US") {
  const formatter = new Intl.NumberFormat(locale, { useGrouping: false });
  const parts = formatter.formatToParts(-1.5);
  const decimal = parts.find(part => part.type === "decimal")?.value ?? ".";
  const minus = parts.find(part => part.type === "minusSign")?.value ?? "-";
  return (Object.is(value, -0) ? "-0" : String(value)).replace(/[0-9.-]/g, character => character === "." ? decimal : character === "-" ? minus : formatter.format(Number(character)));
}

"use client";

import * as React from "react";
import { animate, frameSteps, motionValue, type AnimationPlaybackControls, type Transition } from "motion";
import { getMotionTime, isMotionClockFrozen, registerMotionClock } from "@/lib/cojeev-motion/clock";
import { getSettingsSnapshot, getServerSettingsSnapshot, subscribeSettings, type SettingsSnapshot } from "@/lib/cojeev-motion/settings";
import { useReducedMotion } from "@/lib/cojeev-motion/use-reduced-motion";

/** The shared rhythm. Durations and stagger are seconds, matching Motion's API. */
export const motionTokens = {
  spring: {
    responsive: { type: "spring", stiffness: 360, damping: 32, mass: .85 },
    expressive: { type: "spring", stiffness: 260, damping: 22, mass: 1 },
    gentle: { type: "spring", stiffness: 180, damping: 28, mass: 1 },
  },
  ease: { enter: [.2, .8, .2, 1], exit: [.4, 0, 1, 1], settle: [.2, .65, .25, 1] },
  duration: { quick: .16, enter: .32, exit: .18 },
  stagger: .035,
} as const;

export function resolveChoreography(snapshot: SettingsSnapshot, reduced: boolean): { quiet: boolean; transition: Transition } {
  const quiet = reduced || snapshot.motion.mode === "off" || snapshot.flow.variant === "off";
  if (quiet) return { quiet, transition: { duration: 0, delay: 0 } };
  const speed = snapshot.flow.speed;
  const spring = ["jelly", "rubber", "drop", "pebble"].includes(snapshot.flow.variant)
    ? motionTokens.spring.expressive : motionTokens.spring.responsive;
  return { quiet, transition: { ...spring, stiffness: spring.stiffness * speed * speed, damping: spring.damping * speed } };
}

/** Reactive settings subscription for reusable React surfaces. */
export function useChoreography() {
  const snapshot = React.useSyncExternalStore(subscribeSettings, getSettingsSnapshot, getServerSettingsSnapshot);
  const reduced = useReducedMotion();
  return React.useMemo(() => resolveChoreography(snapshot, reduced), [snapshot, reduced]);
}

/** Connect Motion's JS animations to the existing deterministic document clock. */
export function trackMotion(controls: AnimationPlaybackControls) {
  let origin = getMotionTime() - controls.time * 1000;
  let frozen = isMotionClockFrozen();
  if (frozen) controls.pause();
  const release = registerMotionClock(time => {
    if (time === null) {
      if (frozen) controls.play();
      frozen = false;
      return;
    }
    if (!frozen) {
      origin = time - controls.time * 1000;
      controls.pause();
      frozen = true;
    }
    controls.time = Math.max(0, time - origin) / 1000;
    if (controls.time >= controls.duration) controls.complete();
    // A seek schedules Motion's update phase. Flush it at this explicit sample;
    // normal playback stays entirely on Motion's own animation frame loop.
    frameSteps.update.process({ delta: 0, timestamp: performance.now(), isProcessing: false });
  });
  void controls.finished.then(release, release);
  return () => { release(); controls.stop(); };
}

/** One interruptible spring per scalar; retargets inherit the current value and velocity. */
export function createMotionLane(initial: number, render: (value: number) => void) {
  const value = motionValue(initial);
  const unsubscribe = value.on("change", render);
  let cancel = () => {};
  let generation = 0;
  const stop = () => { generation++; cancel(); cancel = () => {}; value.stop(); };
  const jump = (target: number) => { stop(); value.jump(target); render(target); };
  return {
    get: () => value.get(),
    jump,
    to(target: number, transition: Transition, complete?: () => void) {
      stop();
      if (transition.duration === 0) { jump(target); complete?.(); return; }
      const owner = generation;
      const controls = animate(value, target, {
        ...transition,
        autoplay: !isMotionClockFrozen(),
        onComplete: () => { if (generation === owner) complete?.(); },
      });
      cancel = trackMotion(controls);
    },
    stop,
    dispose: () => { stop(); unsubscribe(); value.destroy(); },
  };
}

/** One document-time clock for springs, cancellable phase timers, then Web Animations. */
export type MotionTimer = {at:number;run:()=>void;native:ReturnType<typeof setTimeout>|null;cancelled:boolean}
let time:number|null=null
const pending=new Set<MotionTimer>()
const drivers=new Set<(time:number|null)=>void>()
const animationStarts=new Map<Animation,{at:number;wasRunning:boolean}>()
const now=()=>time??performance.now()
function arm(timer:MotionTimer){timer.native=setTimeout(()=>{timer.native=null;if(timer.cancelled)return;pending.delete(timer);timer.run()},Math.max(0,timer.at-performance.now()))}
export function scheduleMotion(run:()=>void,delay:number):MotionTimer{
 const timer:MotionTimer={at:now()+Math.max(0,delay),run,native:null,cancelled:false};pending.add(timer)
 if(time===null)arm(timer)
 return timer
}
export function cancelMotion(timer:MotionTimer|null|undefined){if(!timer)return;timer.cancelled=true;if(timer.native!==null)clearTimeout(timer.native);timer.native=null;pending.delete(timer)}
export function registerMotionClock(driver:(time:number|null)=>void){drivers.add(driver);return ()=>{drivers.delete(driver)}}
export function getMotionTime(){return now()}
export function isMotionClockFrozen(){return time!==null}
/** Freeze before an interaction. First spring delta is zero; timer callbacks can enqueue subsequent beats. */
export function motionClock(next:number|null){
 if(next===null){
  const was=time;time=null
  if(was!==null)for(const timer of pending){timer.at=performance.now()+Math.max(0,timer.at-was);arm(timer)}
  drivers.forEach(driver=>driver(null))
  for(const [animation,state] of animationStarts){if(state.wasRunning)animation.play()}
  animationStarts.clear();return
 }
 if(!Number.isFinite(next))throw new Error("Motion clock expects finite milliseconds or null.")
 if(time===null){const real=performance.now();for(const timer of pending){if(timer.native!==null)clearTimeout(timer.native);timer.native=null;timer.at=next+Math.max(0,timer.at-real)}}
 time=next
 drivers.forEach(driver=>driver(next))
 // Due callbacks observe this clock sample, matching the source phase queue.
 let due:MotionTimer|undefined
 while((due=[...pending].filter(timer=>timer.at<=next).sort((a,b)=>a.at-b.at)[0])){
  pending.delete(due);if(due.cancelled)continue;due.run()
 }
 time=next
 if(typeof document!=="undefined"){
  const animations=document.getAnimations()
  for(const animation of animations){
   if(!animationStarts.has(animation)){animationStarts.set(animation,{at:next,wasRunning:animation.playState==="running"});animation.pause()}
   animation.currentTime=Math.max(0,next-animationStarts.get(animation)!.at)
  }
  for(const animation of animationStarts.keys())if(!animations.includes(animation))animationStarts.delete(animation)
 }
}
export const flowClock=motionClock

